import sys
from functools import lru_cache

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = list(map(int, data[1:n+1]))

    @lru_cache(maxsize=None)
    def game(left, right, last):
        # left, right: indices of the remaining subarray a[left..right]
        # last: the last value added to the sequence
        # Returns True if the current player (to move) can force a win

        # Check if any move is possible
        can_move_left = left <= right and a[left] > last
        can_move_right = left <= right and a[right] > last

        if not can_move_left and not can_move_right:
            return False  # No move, current player loses

        # Try left move
        if can_move_left:
            if not game(left + 1, right, a[left]):
                return True
        # Try right move
        if can_move_right:
            if not game(left, right - 1, a[right]):
                return True

        return False

    # Initial state: empty array, no last value. Use -infinity for last.
    # But a[i] >= 0, so -1 works, or we can use a sentinel.
    result = game(0, n - 1, -1)

    if result:
        print("Alice")
    else:
        print("Bob")

if __name__ == "__main__":
    main()
