import sys
from functools import lru_cache

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    memo = {}

    def can_win(l, r, last):
        if l > r:
            return False
        key = (l, r, last)
        if key in memo:
            return memo[key]

        result = False
        if l <= r:
            if a[l] > last:
                if not can_win(l+1, r, a[l]):
                    result = True
            if a[r] > last:
                if not can_win(l, r-1, a[r]):
                    result = True
            if not result and a[l] <= last and a[r] <= last:
                result = False
            memo[key] = result
            return result
        memo[key] = False
        return False

    if can_win(0, n-1, -1):
        print("Alice")
    else:
        print("Bob")

solve()
