import sys

def main():
    data = sys.stdin.read().splitlines()
    s = data[0].strip()
    x_str = data[1].strip()

    n = len(s)
    x_len = len(x_str)

    x_digits = [ord(c) - 48 for c in x_str]
    s_digits = [ord(c) - 48 for c in s]

    def check(a, b, c):
        L1 = b - a
        L2 = c - b
        carry = 0
        for i in range(x_len):
            d1 = 0
            if i < L1:
                d1 = s_digits[b - 1 - i]
            d2 = 0
            if i < L2:
                d2 = s_digits[c - 1 - i]
            total = d1 + d2 + carry
            if total % 10 != x_digits[x_len - 1 - i]:
                return False
            carry = total // 10
        if carry != 0:
            return False
        return True

    if x_len == 1:
        candidates_L = [1]
        candidates_R = [1]
    else:
        candidates_L = [x_len, x_len - 1]
        candidates_R = [x_len, x_len - 1]

    for b in range(1, n):
        for L in candidates_L:
            if L > b or L < 1:
                continue
            a = b - L
            for R in candidates_R:
                if R > n - b or R < 1:
                    continue
                c = b + R
                if check(a, b, c):
                    print(f"{a+1} {b}")
                    print(f"{b+1} {c}")
                    return

    # Fallback: try all possible lengths
    for b in range(1, n):
        for L in range(1, min(b, x_len) + 1):
            a = b - L
            for R in range(1, min(n - b, x_len) + 1):
                c = b + R
                if check(a, b, c):
                    print(f"{a+1} {b}")
                    print(f"{b+1} {c}")
                    return

