def solve():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    A = list(map(int, data[1:n+1]))

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def game(l, r, last):
        if l > r:
            return False
        can = False
        if l <= r:
            if A[l] > last:
                can = not game(l+1, r, A[l])
            if not can and r >= l:
                if A[r] > last:
                    can = not game(l, r-1, A[r])
        return can

    print("Alice" if game(0, n-1, -1) else "Bob")

